sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    var TradetaskType = g_form.getValue('trade_task_type');
    var outcome = g_form.getValue('outcome');
	var state = g_form.getValue('state');

    try {
        if (TradetaskType == 'Checker' && outcome.length > 40) {
            g_form.hideAllFieldMsgs();
            g_form.showFieldMsg('outcome', 'Please refer to the Comments and Task History tab for the full outcome value.', 'info');
        }

        var owningBusiness = g_scratchpad.owningBus.toString();

        //Tran Reference For Swift Linking
        if (TradetaskType == 'Maker' && state != '3') {

            if (owningBusiness.indexOf('UK') == -1) { //added as part of 3916  // for Non UK 
                g_form.showFieldMsg("tran_reference_for_swift_linking", getMessage("Custody Tran Reference for SWIFT Linking Non-UK"), "info");
            }

            if (owningBusiness.indexOf('UK') > -1) { //added as part of 3916   // for UK 
                g_form.showFieldMsg("tran_reference_for_swift_linking", getMessage("Custody Tran Reference for SWIFT Linking UK"), "info");

            }
        }
		else{
			g_form.hideFieldMsg("tran_reference_for_swift_linking");
		}
		if (TradetaskType == 'Checker'){
			g_form.hideFieldMsg("tran_reference_for_swift_linking");
		}

    } catch (error) {

    }







}
